        "Delta": 3, "Epsilon": 2, "Zeta":10, "Eta": 6,
        "Theta": 3, "Iota": 1, "Kappa": 7
    },
    "Eta": {
        "Delta":10, "Epsilon":7, "Zeta": 8, "Eta": 2,
        "Theta": 2, "Iota": 7, "Kappa": 9
    }
}

# ----------------------------------------------------------------------
# Model
# ----------------------------------------------------------------------
model = pulp.LpProblem("PowerGrid_MinCost", pulp.LpMinimize)

# Decision variables: flow from plant i to hub j (continuous, >=0)
flow = pulp.LpVariable.dicts(
    "flow",
    ((p, h) for p in plants for h in hubs),
    lowBound=0,
    cat=pulp.LpContinuous
)

# Objective: minimize total transmission cost
model += pulp.lpSum(
    line_cost[p][h] * flow[(p, h)] for p in plants for h in hubs
), "Total_Transmission_Cost"

# Supply constraints: each plant cannot exceed its generation capacity
for p in plants:
    model += (
        pulp.lpSum(flow[(p, h)] for h in hubs) <= plant_capacity[p],
        f"Supply_{p}"
    )

# Demand constraints: each hub must receive exactly its required MW
for h in hubs:
    model += (
        pulp.lpSum(flow[(p, h)] for p in plants) == hub_demand[h],
        f"Demand_{h}"
    )

# Line capacity constraints
for p in plants:
    for h in hubs:
        model += (
            flow[(p, h)] <= line_capacity[p][h],
            f"Cap_{p}_{h}"
        )

# ----------------------------------------------------------------------
# Solve
# ----------------------------------------------------------------------
solver = pulp.HiGHS(msg=False, timeLimit=120)
model.solve(solver)

